/**
 * Server-generated suggestion screens (goals, personality, ideals, bonds,
 * flaws).
 *
 * Every suggestion is generated by the MUD — the browser never invents prompts
 * or themes them from a background it guessed at. Choosing a suggestion only
 * seeds the in-memory draft; it never commits anything on its own.
 */

import { ChoiceGallery } from './ChoiceGallery.tsx';
import type { ScreenProps } from './screen-props.ts';

export function RoleplayIdeaScreen(props: ScreenProps) {
  const { state, ui, onAction, onEditorDraftChange } = props;
  const examples = state.examples ?? [];
  const canGenerate = state.actions.includes('generate-example');
  const canContinue = state.actions.includes('continue');

  return (
    <div className="rp-ideas">
      {state.choices.length > 0 ? (
        <section className="rp-idea-themes" aria-label="Suggestion themes">
          <p className="rp-idea-guidance">
            Choose a background theme to ask the world for matching suggestions.
          </p>
          <ChoiceGallery
            {...props}
            layout="grid"
            allowInspect
            emptyMessage="The world offered no suggestion themes."
          />
        </section>
      ) : null}

      {examples.length === 0 ? (
        <p className="rp-empty">
          {canGenerate
            ? 'No suggestions yet. Ask for some, or continue and write your own.'
            : 'The world offered no suggestions here. Continue and write your own.'}
        </p>
      ) : (
        <ul className="rp-idea-list">
          {examples.map((example) => (
            <li key={example.id} className="rp-idea">
              <p className="rp-idea-text">{example.text}</p>
              {onEditorDraftChange ? (
                <button
                  type="button"
                  disabled={ui.pending}
                  aria-pressed={ui.ideaDraft?.draft === example.text}
                  // Seeds the draft only. The player still edits and saves it
                  // explicitly, so a suggestion can never become a silent commit.
                  onClick={() => onEditorDraftChange(example.text)}
                >
                  {ui.ideaDraft?.draft === example.text
                    ? 'Starting point selected'
                    : 'Use this as a starting point'}
                </button>
              ) : null}
            </li>
          ))}
        </ul>
      )}

      <div className="rp-actions">
        {canGenerate ? (
          <button type="button" disabled={ui.pending} onClick={() => onAction('generate-example')}>
            Suggest something else
          </button>
        ) : null}
        {canContinue ? (
          <button
            type="button"
            className="rp-primary"
            disabled={ui.pending}
            onClick={() => onAction('continue')}
          >
            Write it myself
          </button>
        ) : null}
        {state.actions.includes('cancel') ? (
          <button type="button" disabled={ui.pending} onClick={() => onAction('cancel')}>
            Back to profile
          </button>
        ) : null}
      </div>
    </div>
  );
}
